/**
 * Animator: keys generated by tools/avatar/build_clips.py, then made shorter by hand: 5.0 s instead
 *           of 6.47 s (build_clips.py leaves this file alone). Only the two holds are shortened (the
 *           first, nearly still part and the hold before lowering); the movements keep their speed.
 * Sign id:  not_good
 * Myanmar:  မကောင်းဘူး
 * English:  Not good
 * Source:   28 recorded takes of signer "pmt" (data/msl77/raw/pmt/not_good),
 *           time-aligned (DTW) and averaged, then retargeted onto the character.
 */
import type { Object3D } from 'three'
import { mirrorKeys } from './mirrored'
import { createRecordedClip, type RecordedKey } from './recorded'

export const NOT_GOOD_DURATION = 5.0
/** Recorded holds [start, end] and their new lengths (s); everything else keeps its recorded speed. */
const SHORTENED: [number, number, number][] = [[.842, 3.103, .95], [5.364, 5.714, .19]]
/** Recorded time -> new time: each shortened hold is compacted, the rest only moves earlier. */
const retime = (time: number) => {
  let shift = 0
  for (const [start, end, length] of SHORTENED) {
    if (time <= start) break
    if (time < end) return start - shift + (time - start) * length / (end - start)
    shift += end - start - length
  }
  return time - shift
}

