export function createNotGoodAnimation(model: Object3D) {
  // Mirrored: played on the character's right hand (a two-handed sign swaps hands).
  const shorter = keys.map(([time, right, left]): RecordedKey => [+retime(time).toFixed(3), right, left])
  return createRecordedClip(model, mirrorKeys(shorter), NOT_GOOD_DURATION)
}
